'use strict';
(async () => {
  const fs = require('node:fs');
  const path = require('node:path');

  const targetFileId = '1MxvFWzM9b-HnZlfr29kzmbqx5BbBetOK';
  const runId = 'drive_takeout_inventory_20261007_1';
  const endpointUrl = 'https://script.google.com/macros/s/AKfycbxz7tkba4wl-wWzDn90iuh0us2l2EUD3AYV9HyVJckETKGjhPKFthnqPyYmcOPOk_g5FA/exec';
  const receiptPath = path.resolve(process.cwd(), 'untrusted AI/meta-procedure/Procedures/DriveTakeoutInventory/latest-result.json');

  const remoteCode = `(input) => {
    try {
      const file = DriveApp.getFileById(input.fileId);
      const info = {
        sourceFileId: file.getId(),
        sourceName: file.getName(),
        sourceBytes: file.getSize(),
        mimeType: file.getMimeType(),
        inspectedAt: new Date().toISOString()
      };

      let entries = null;
      let status = 'METADATA_ONLY';
      let errorMsg = null;

      try {
        const blob = file.getBlob();
        const unzipped = Utilities.unzip(blob);
        entries = unzipped.map(b => ({ name: b.getName(), bytes: b.getSize() }));
        status = 'ENUMERATED';
      } catch (unzipErr) {
        errorMsg = 'Decompression bypassed or failed: ' + String(unzipErr.message || unzipErr);
      }

      const report = {
        runId: input.runId,
        status: status,
        metadata: info,
        entryCount: entries ? entries.length : null,
        entries: entries,
        archiveModified: false,
        unzipDiagnostic: errorMsg
      };

      const reportName = 'takeout-archive-inspection-' + input.runId + '.json';
      const reportFile = DriveApp.createFile(reportName, JSON.stringify(report, null, 2), MimeType.PLAIN_TEXT);

      return {
        status: status,
        sourceFileId: info.sourceFileId,
        driveFileId: reportFile.getId(),
        driveFileUrl: reportFile.getUrl(),
        sourceBytes: info.sourceBytes,
        archiveModified: false,
        entryCount: entries ? entries.length : null,
        unzipDiagnostic: errorMsg
      };
    } catch (fatalErr) {
      return {
        status: 'FAILED',
        sourceFileId: input.fileId,
        driveFileId: null,
        driveFileUrl: null,
        archiveModified: false,
        error: String(fatalErr.message || fatalErr)
      };
    }
  }`;

  const payload = {
    sourcecode: remoteCode,
    arguments: {
      fileId: targetFileId,
      runId: runId
    }
  };

  let attempt = 0;
  let response = null;
  let resultText = '';
  const maxRetries = 2;

  while (attempt <= maxRetries) {
    try {
      process.stdout.write(`[DriveTakeoutInventory] Dispatching attempt ${attempt + 1}/${maxRetries + 1} to Apps Script bridge...\n`);
      response = await fetch(endpointUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
        redirect: 'follow',
        signal: AbortSignal.timeout(180000)
      });
      resultText = await response.text();
      if (response.ok) break;
      process.stderr.write(`[DriveTakeoutInventory] HTTP ${response.status}: ${resultText.slice(0, 300)}\n`);
    } catch (netErr) {
      process.stderr.write(`[DriveTakeoutInventory] Network error on attempt ${attempt + 1}: ${netErr.message}\n`);
    }
    attempt++;
    if (attempt <= maxRetries) {
      await new Promise(r => setTimeout(r, 1000 * attempt));
    }
  }

  if (!response || !response.ok) {
    throw new Error(`Apps Script bridge dispatch failed after ${maxRetries + 1} attempts. Last response: ${resultText.slice(0, 500)}`);
  }

  let result;
  try {
    result = JSON.parse(resultText);
  } catch (parseErr) {
    throw new Error(`Apps Script bridge returned non-JSON body: ${resultText.slice(0, 500)}`);
  }

  if (result.status === 'FAILED' || !result.driveFileId || !result.driveFileUrl) {
    throw new Error(`Remote execution failed or missing Drive report evidence: ${JSON.stringify(result)}`);
  }

  if (result.archiveModified !== false || result.driveFileId === targetFileId) {
    throw new Error(`CRITICAL INVARIANT VIOLATION: Source archive was modified or report ID matches source ID!`);
  }

  fs.mkdirSync(path.dirname(receiptPath), { recursive: true });
  fs.writeFileSync(receiptPath, JSON.stringify(result, null, 2) + '\n', 'utf8');
  process.stdout.write(`[DriveTakeoutInventory] Verified inspection complete. Report created in Drive: ${result.driveFileUrl}\n`);
  process.stdout.write(`[DriveTakeoutInventory] Receipt written to ${receiptPath}\n`);
  console.log(JSON.stringify(result));
})().catch(err => {
  process.stderr.write(`[DriveTakeoutInventory-FATAL] ${err.stack || err.message}\n`);
  process.exitCode = 1;
});
